requests.query:
Convert this JavaScript to a Python function `chunk(arr: list, size: int) -> list` with the same behaviour:

function chunk(arr, size) {
  const out = [];
  for (let i = 0; i < arr.length; i += size) {
    out.push(arr.slice(i, i + size));
  }
  return out;
}

requests.test:
assert word_count("The cat. The DOG!") == {"the": 2, "cat": 1, "dog": 1}
assert word_count("") == {}
assert word_count("don't stop") == {"don't": 1, "stop": 1}
assert word_count("a-b a") == {"a": 2, "b": 1}

requests.query:
Convert this JavaScript to a Python function `group_by(items, key_fn) -> dict` that returns a dict mapping each key to the list of items with that key, in input order:

const groupBy = (items, keyFn) => items.reduce((acc, item) => {
  const k = keyFn(item);
  (acc[k] = acc[k] || []).push(item);
  return acc;
}, {});

requests.test:
assert group_by([1, 2, 3, 4, 5], lambda x: x % 2) == {1: [1, 3, 5], 0: [2, 4]}
assert group_by([], len) == {}
assert group_by(["a", "bb", "c"], len) == {1: ["a", "c"], 2: ["bb"]}

